from 写入第二遍 import add
add('17_002',7,'16:9，青侧脸与武士头侧的双人近景，青居画面左侧、握拳在颊旁，武士头部圆弧在右侧近层压入；摄影机随二人高处惯性漂移，落幅维持两只眼睛接近同高的对视关系。','青从下方追上后停在武士头侧，长发继续朝来路飘；她拳头护在颊旁，圆睁双眼盯住对方，先抬一点下巴把反问送出去。武士白眼停在她脸上，迟迟没有回应；青嘴角绷住，眉梢再压低一点，接着把第二句说清，五指在拳里又扣紧。话落后她仍维持对视，发尾从大幅飘动收成缓慢摆动，武士眼隙侧缘轻颤。','两张脸与拳外的空隙是浅蓝灰云天，稀薄冷灰云纹慢慢下移，平台与地面不入画。','开阔云天冷白漫射照亮青脸与拳背，武士头侧保持冷灰弧面，双方光向一致。','追来的尖风散成高处气流声，青护腕轻绷；话间留一小拍只听风的空隙。',ja=['どうしたの？何か言ってよ。','全力を出せって言ったのは、そっちでしょ。'],tone='青第一句主动追问，后半句催他回答；第二句带回敬挑衅的笃定，语尾收紧，武士沉默。',kind='mixed',phase='state',node={'叙事阶段':'青在高空头旁反问，接旁观交锋远景','青.位置':'武士头侧近处，高空'},meaning='青握拳侧脸与武士头侧同高的逼近关系保留，两句反问后切远，不补近处收尾招式。',motion='双方高处惯性漂移，摄影机跟住对视；青发尾顺来路飘，眼睛与拳保持相对位置。',ground='两人均无地面支点，位置由既有升势与追近接续。',characters=['青','鬼头武士'],card={'opening':'青把先前的挑衅原样还给武士。','beats':['护拳抬下巴，主动追问','对方沉默时维持注视','眉再压、拳扣紧，把第二句落定'],'coupling':'青的提问留给对方一拍回应空间，沉默推动她继续追逼。','landing':'双方对视仍在高空，下一镜退回旁观距离。'})
add('18_001',1.5,'16:9，从城镇方向仰看的极远景，云天占满画幅，两小团人物黑影挤在中央上方，交叉白芒由交叠点伸出；固定机位，始终保持旁观距离。','两小团身影在高处短促交叠，交点猛亮一下，四道细白芒向外拉开；黑影被亮点遮住极短一拍，亮点随即缩紧。云层仍按原方向缓慢漂移，人物具体手脚留在远得无法分辨的尺度里。','蓝灰云天层层展开，中央云隙略浅，外围较深灰云围成不规则大面。','冷白云光为环境底，交叠点短促白亮后立刻收束，云层只受一瞬画面提亮。','高处一声极短闷击隔着距离传来，随后一小段低频空隙。',phase='contact',node={'叙事阶段':'旁观远景见高空闪点交锋'},meaning='严格沿漫画旁观者远景，只见两小身影与闪点，不补可辨的空中拳脚收尾。',motion='远处小黑影短交叠，机位不追近，白芒由中心向四周拉开。',ground='人物均远在高空，地面在画外。',characters=[])
add('18_002',2.5,'16:9，沿同一城镇旁观方向仰看的云天远景，中心亮点居画面中央偏左，上下两道外圈白弧从边缘通过；固定机位让内环到外环依次展开。','小亮点先缩成尖白核，紧贴它的一圈齿状白环猛向外扩，随后更大的环弧赶到画面四边；环缘短线一根根向外倒伏，云层被环形画线切开又重新露出。中心仍远得看不清人物，外圈越过边缘后，只留一条向下收细的远处亮迹。','深浅蓝灰云层铺满天空，中心附近浅云被白色同心环形图形分开，外缘淡冷灰云纹在白弧后显回。','云天冷白光稳定，白核与环缘只在冲击重音上短促提亮，图形过后环境明度回稳。','延迟到达的一声低沉空爆扩开成宽回响，接远处向下拉长的细风声。',phase='result',node={'叙事阶段':'旁观冲击环扩散，坠落开始'},meaning='原格扩散白环、亮点与云天完整保留，观察距离和未显出的手脚过程保持原漫画处理。',motion='同心白环由中心扩到画外，中心远迹转向下方，摄影机始终不接近人物。',ground='空中结果转入下坠，接触平台尚未发生。',characters=[])
